{
  "_source": "db_ground_truth",
  "_note": "Truncated for display (10 products matched)",
  "products": [
    {
      "id": "1YMWWN1N4O",
      "name": "Eclipsmart Travel Refractor Telescope",
      "price": 129.95,
      "avg_score": 4.6,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "solar_viewer",
          "score": 5.0,
          "text": "Perfect for solar observations! The Solar Safe filter gives peace of mind. I used it for the last partial eclipse and it was fantastic."
        },
        {
          "reviewer": "sun_gazer",
          "score": 5.0,
          "text": "Very impressed with the safety features and clarity. Sharing the sun with family has never been easier or safer. Great value for a dedicated solar scope."
        }
      ]
    },
    {
      "id": "L9ECAV7KIM",
      "name": "Lens Cleaning Kit",
      "price": 21.95,
      "avg_score": 4.6,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "tech_maintenance",
          "score": 5.0,
          "text": "Great value for money. The different cleaning options cover all needs. Keeps my expensive equipment in pristine condition."
        },
        {
          "reviewer": "clean_optics",
          "score": 5.0,
          "text": "This kit is a lifesaver for all my optics. The brush and wipes work perfectly without leaving any residue. My lenses have never been cleaner."
        }
      ]
    },
    {
      "id": "OLJCESPC7Z",
      "name": "National Park Foundation Explorascope",
      "price": 101.96,
      "avg_score": 3.8,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "stargazer_mike",
          "score": 4.5,
          "text": "Great entry-level telescope! Easy to set up and provides clear views of the moon and brighter planets. Highly recommend for new astronomers."
        },
        {
          "reviewer": "nightskylover",
          "score": 4.0,
          "text": "For the price, this Explorascope delivers excellent performance. I was able to see Jupiter's moons clearly. A fantastic purchase for casual viewing."
        }
      ]
    },
    {
      "id": "9SIQT8TOJO",
      "name": "Optical Tube Assembly",
      "price": 3599.0,
      "avg_score": 4.8,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "deep_sky_master",
          "score": 5.0,
          "text": "The RASA V2 is a dream come true for deep-sky imaging. The f/2.2 speed drastically cuts down exposure times. My best astrophotography investment yet."
        },
        {
          "reviewer": "pro_astro",
          "score": 5.0,
          "text": "Unbelievable performance for wide-field astrophotography. The short focal length makes guiding less critical. Produces stunning, detailed images."
        }
      ]
    },
    {
      "id": "LS4PSXUNUM",
      "name": "Red Flashlight",
      "price": 57.08,
      "avg_score": 4.6,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "astro_accessory",
          "score": 5.0,
          "text": "Every astronomer needs one of these. The red light is essential, and the hand warmer and power bank make it incredibly useful. A top-tier accessory."
        },
        {
          "reviewer": "night_walker",
          "score": 5.0,
          "text": "The red light is perfect for preserving night vision during techx sessions. The hand warmer is an unexpected bonus. Very practical device."
        }
      ]
    },
    {
      "id": "2ZYFJ3GM2N",
      "name": "Roof Binoculars",
      "price": 209.95,
      "avg_score": 4.4,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "bird_watcher",
          "score": 5.0,
          "text": "Incredible clarity and brightness, perfect for bird watching. The ED glass really makes a difference. I can spot the subtlest markings."
        },
        {
          "reviewer": "outdoor_adventurer",
          "score": 4.5,
          "text": "Excellent build quality and optical performance. They feel robust and provide sharp images. A great investment for any outdoor activity."
        }
      ]
    },
    {
      "id": "6E92ZMYYFZ",
      "name": "Solar Filter",
      "price": 69.95,
      "avg_score": 4.8,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "eclipse_ready",
          "score": 5.0,
          "text": "Bought this for the upcoming eclipse, and it fits perfectly. Tested it out, and the views are fantastic and safe. Very happy with this purchase."
        },
        {
          "reviewer": "solar_safety",
          "score": 5.0,
          "text": "Essential for safe solar viewing with my 8-inch telescope. The Velcro straps ensure it stays securely in place. Peace of mind during solar observations."
        }
      ]
    },
    {
      "id": "0PUK6V6EV0",
      "name": "Solar System Color Imager",
      "price": 175.0,
      "avg_score": 4.6,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "space_artist",
          "score": 5.0,
          "text": "The detail I can capture with this imager is incredible. It integrates well with various software. A must-have for serious planetary observers."
        },
        {
          "reviewer": "astro_photog",
          "score": 5.0,
          "text": "This imager is a fantastic step up for planetary photography. The color quality is superb. Easy to use with my existing telescope setup."
        }
      ]
    },
    {
      "id": "66VCHSJNUP",
      "name": "Starsense Explorer Refractor Telescope",
      "price": 349.95,
      "avg_score": 4.6,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "clear_skies",
          "score": 5.0,
          "text": "Finally, a telescope that takes the guesswork out of stargazing. The real-time positioning is incredibly accurate. Highly recommended for anyone new to techx."
        },
        {
          "reviewer": "tech_astro",
          "score": 5.0,
          "text": "The StarSense app is revolutionary! It made finding celestial objects incredibly easy. This telescope is a game-changer for beginners."
        }
      ]
    },
    {
      "id": "HQTGWGPNH4",
      "name": "The Comet Book",
      "price": 0.99,
      "avg_score": 4.6,
      "review_count": 5,
      "reviews_sample": [
        {
          "reviewer": "history_buff",
          "score": 5.0,
          "text": "A fascinating glimpse into historical astronomical thought. The content is incredibly insightful. A must-read for anyone interested in the history of science."
        },
        {
          "reviewer": "celestial_history",
          "score": 5.0,
          "text": "I love historical techx, and this book delivers. It's well-researched and provides a window into past beliefs. Highly recommended for scholars."
        }
      ]
    }
  ]
}

